<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define ms(s, n) memset(s, n, sizeof(s))
#define FOR(i, a, b) for(int i = (a); i < (b); i++)
#define FORd(i, a, b) for(int i = (a) - 1; i >= (b); i--)
#define rep(i, a, b) for(int i = (a); i < (b); i++)
#define sz(a) int((a).size())
#define all(a) (a).begin(), (a).end()
#define pb push_back
#define mp make_pair
#define fi first
#define se second
typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;
typedef pair<int, int> pi;
typedef vector<int> vi;
typedef vector<pi> vii;
typedef pair<ll, ll> lll;
ll gcd(ll a, ll b) {ll r; while (b != 0) {r = a % b; a = b; b = r;} return a;}
ll lcm(ll a, ll b) {return a / gcd(a, b) * b;}
#define EPS 1e-9
const int mod = (int) 1e9 + 7;
const int INF = (int) 1e9;
const ll LINF = (ll) 1e18;
const ld PI = 2 * acos(0);
const int M = 50;
const int N = 1e6 + 7;


ll pw(ll x, ll k){
    if (!k) return 1;
    if (k & 1) return x * pw(x, k - 1) % mod;
    ll t = pw(x, k / 2);
    return t * t % mod;
}


ll get(ll x, ll k, ll n){
    if (!k) return 1 % n;
    if (k & 1) return x * get(x, k - 1, n) % n;
    ll t = get(x, k >> 1, n);
    return t * t % n;
}

int n, k;
int a[N];
int check[N];



void solve() {
    cin >> n >> k;
    if (k == 0){
        cout << pw(k, k - 1);
        return;
    }
    if (k == 1){
        cout << pw(k, k);
        return;
    }
    for(int d = 0; d < n; d++){
        a[d] = (ll) d * k % n;
    }
    ll ans = 1;
    for(int d = 0; d < n; d++)
        if (!check[d]){
            check[d] = 1;
            d = a[d];
            int cnt = 1;
            while (!check[d]){
                d = a[d];
                cnt++;
            }
            if (get(k, cnt, n) == 1){
                ans = (ans * n) % mod;
            }
        }
    cout << ans;

}

int main() {
    //ios_base::sync_with_stdio(0); cin.tie(NULL);
#ifndef ONLINE_JUDGE
    freopen("in.txt", "r", stdin); //freopen("out.txt", "w", stdout);
#endif

    solve();
#ifdef _LOCAL_
    //printf("\nTime elapsed: %dms", 1000 * clock() / CLOCKS_PER_SEC);
#endif
    return 0;
}

